 void VerifyMidCostTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Mid cost peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mid cost mulligan");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Mid cost mulligans done");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}int drake=Inject(g,"EX1_043"),big=Inject(g,"EX1_005"),mukla=Inject(g,"EX1_014");var giant=g.Summon(1,"VAN_CS2_182");giant.BuffAttack=3;PublishLan();BeginCard(drake);ClickEmptySlot(0,0);PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.CardId=="VAN_EX1_043"&&u.MaxHealth==3),"Twilight Drake hand count buff synchronized");BeginCard(big);ClickEmptySlot(0,1);Check(pending=="play","Big Game Hunter waits for battlecry target");ClickMatchTarget(new MatchTarget(1,giant.Id));PumpLan(()=>guest.match.Players[1].Board.Count==0&&guest.match.Players[0].Board.Count==2,"Seven attack enemy destroyed");BeginCard(mukla);ClickEmptySlot(0,2);PumpLan(()=>guest.match.Players[1].Hand.Count(h=>h.CardId=="GAME_BANANA")==2,"Generated bananas privately reach guest");Check(LanProtocol.View(g,0,"mid",1).Players[1].Hand.Length==0,"Bananas absent from opponent hand snapshot");Render(Path.Combine(folder,"139-mid-cost-battlecries-codex.png"));DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest mid cost turn");
  foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=10;}var cult=g.Summon(0,"VAN_EX1_595");var ghoul=g.Summon(0,"VAN_tt_004");g.Summon(0,"VAN_CS2_231");g.Summon(1,"VAN_CS2_231");int whirlwind=Inject(g,"EX1_400",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==whirlwind),"Guest Whirlwind received");guest.BeginCard(whirlwind);PumpLan(()=>!guest.lanWaiting&&guest.match.Players[0].Board.Any(u=>u.Id==ghoul.Id&&u.BuffAttack==2),"Death notifications synchronize buffs");Check(g.Players[0].Hand.Count==1&&guest.match.Players[0].Hand.Count==0,"Cult draws one friendly death and opponent cannot see card");guest.Opacity=1;guest.Render(Path.Combine(folder,"140-mid-cost-death-triggers-codex.png"));guest.Opacity=0;
  g.Players[0].Hand.Clear();var bot=g.Summon(0,"VAN_EX1_006");Inject(g,"CS2_181",0);PublishLan();PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.Id==bot.Id),"Alarm Bot public board update");guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&guest.match.Active==0&&guest.match.Players[0].Board.Any(u=>u.CardId=="VAN_CS2_181"),"Alarm Bot next turn swap synchronized");Check(g.Players[0].Board.Single(u=>u.CardId=="VAN_CS2_181").Health==7&&g.Players[0].Hand.Any(h=>h.CardId=="VAN_EX1_006"),"Swap suppresses self damage battlecry and returns bot");Check(guest.match.Players[0].Hand.Count==0,"Swapped hand remains private");
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
